/* Акцессоры цвета: единственный источник — colors.json. */
const C = TABLES.colors.palettes;
TABLES.elementColor = (id) => C.elements.byId[id] || null;
TABLES.meridianColor = (id) => C.meridians.byId[id] || null;
TABLES.starColor = (n) => (C.stars.byNumber[String(n)] || {}).hex || null;
export default TABLES;
